<?php
namespace App\Console\Commands;use App\Services\DevOps\{EnvironmentComparisonService,PlatformStatusService,IntegrationStatusService,PromotionEligibilityService};use Illuminate\Console\Command;
final class DevOpsStatusCommand extends Command {protected $signature='zigo:devops-status {--environment=stage} {--json}';protected $description='Estado enterprise persistido sin ejecutar checks.';public function handle(EnvironmentComparisonService $comparison,PlatformStatusService $platform,IntegrationStatusService $integrations,PromotionEligibilityService $promotion):int{$e=(string)$this->option('environment');if(!in_array($e,['stage','production'],true))return self::INVALID;$r=['environment'=>$e,'comparison'=>$comparison->compare(),'platform'=>$platform->current($e),'integrations'=>$integrations->current($e),'promotion'=>$promotion->evaluate()];$this->line($this->option('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES):'Stage vs PRD: '.$r['comparison']['status'].'; promoción: '.($r['promotion']['eligible']?'eligible':'blocked'));return self::SUCCESS;}}
